const ROT=[["A","B","C","D"],["D","A","B","C"],["C","D","A","B"],["B","C","D","A"]];
const T4=["12:00","13:10","14:30","16:00"],T32=[["12:00","13:20","14:40","16:00"],["11:00","12:20","13:40","15:00"],["12:00","13:20","14:40","16:00"],["12:00","13:20","14:40","16:00"]];
