for(const rid in SDAYS)SDAYS[rid].forEach((d,i)=>{if(SOV.days&&SOV.days[d])return;ROT[i].forEach((g,j)=>SCH.push({rid,d,t:(rid=="r32"?T32[i]:T4)[j],g,n:i+1}))});
