const DOV={en:["Racing day over",n=>`${n} race${n==1?"":"s"} sailed`,g=>`${g} postponed`],de:["Renntag beendet",n=>`${n} Rennen gesegelt`,g=>`${g} verschoben`],fr:["Journée de course terminée",n=>`${n} course${n>1?"s":""} disputée${n>1?"s":""}`,g=>`${g} reporté(s)`],es:["Jornada terminada",n=>`${n} regata${n==1?"":"s"} disputada${n==1?"":"s"}`,g=>`${g} aplazado(s)`],pt:["Dia de regatas encerrado",n=>`${n} regata${n==1?"":"s"} disputada${n==1?"":"s"}`,g=>`${g} adiado(s)`],zh:["今日比赛结束",n=>`已完成 ${n} 场`,g=>`${g} 延期`],ar:["انتهى يوم السباقات",n=>`أُقيم ${n} سباق`,g=>`تأجيل ${g}`],hi:["आज की रेस समाप्त",n=>`${n} रेस हुईं`,g=>`${g} स्थगित`],bn:["আজকের রেস শেষ",n=>`${n}টি রেস হয়েছে`,g=>`${g} স্থগিত`],ur:["آج کی ریسیں ختم",n=>`${n} ریس ہوئیں`,g=>`${g} ملتوی`],id:["Hari lomba selesai",n=>`${n} balapan selesai`,g=>`${g} ditunda`],ms:["Hari perlumbaan tamat",n=>`${n} perlumbaan selesai`,g=>`${g} ditangguhkan`],ja:["本日のレース終了",n=>`${n}レース実施`,g=>`${g} 延期`],th:["จบการแข่งขันวันนี้",n=>`แข่งแล้ว ${n} รายการ`,g=>`${g} เลื่อนออกไป`],hu:["Versenynap vége",n=>`${n} futam lement`,g=>`${g} elhalasztva`],cs:["Závodní den skončil",n=>`Odjeto závodů: ${n}`,g=>`${g} odloženo`],uk:["Гоночний день завершено",n=>`Проведено гонок: ${n}`,g=>`${g} перенесено`],pl:["Dzień regat zakończony",n=>`Rozegrane wyścigi: ${n}`,g=>`${g} przełożone`],it:["Giornata conclusa",n=>`${n} ${n==1?"regata disputata":"regate disputate"}`,g=>`${g} ${/&| e /.test(g)?"rinviati":"rinviato"}`]};
const dayOver=d=>!!(FLG&&FLG.days&&FLG.days[d]&&FLG.days[d].over);
const APA='<svg class="apa" viewBox="0 0 40 28" width="34" height="24" aria-hidden="true"><rect x="1" y="1" width="38" height="12" rx="2" fill="#fff"/><path d="M1 3h38M1 6h38M1 9h38" stroke="#e53935" stroke-width="2.2"/><rect x="5" y="15" width="30" height="12" rx="2" fill="#fff"/><path d="M5 15h15l-4 6 4 6H5z" fill="#1a4486"/></svg>';
function dayOverBox(list,d){const D0=DOV[lang]||DOV.en,done=list.filter(x=>x.d==d&&raceDone(x)).length,mv=list.filter(x=>x.d==d&&!raceDone(x)),fm=(FLG.days[d]||{}).moved||[];
  const gs=mv.length?mv.map(x=>x.rid=="f"||x.rid=="pf"?RNm(rnd(x.rid)):x.g):fm;const gl=gs.length?(mv.every(x=>x.rid!="f"&&x.rid!="pf")?`${T("group")} ${gs.join(" & ")}`:gs.join(" & ")):"";
  return `<li class="rdover">${APA}<span><b>${esc(D0[0])}</b><small>${esc(D0[1](done))}${gl?" · "+esc(D0[2](gl)):""}</small></span></li>`}
function raceList(list){const all=[...list],L0=list.filter(x=>!(dayOver(x.d)&&!raceDone(x))),nx=L0.filter(x=>rState2(x)=="up").sort((a,b)=>at(a)-at(b))[0],ds=[...new Set(all.map(x=>x.d))].filter(dayOver);
  return `<ul class="races">${L0.sort((a,b)=>at(a)-at(b)).map(x=>raceLi(x,nx)).join("")}${ds.map(d=>dayOverBox(all,d)).join("")}</ul>`}
function tzNote(){return `<small style="display:block;color:var(--mute);font-size:12px;margin-top:8px">${T("rioT")}${showLocal?` · ${T("loc")} (${esc(myTZ)})`:""}${WX?` · <span title="${esc(T("wxSrc"))}">↓ kn = ${esc(T("wxT"))}</span>`:""}</small>`}
function schedFor(r){const L=SCH.filter(x=>x.rid==r.id||(r.id=="f"&&x.rid=="pf"));if(!L.length)return"";const days=[...new Set(L.map(x=>x.d))];
  return `<details class="sched g"><summary>${T("schedT")}</summary>${days.map(d=>`<div class="sday"><h5>${esc(wday(d))}</h5>${raceList(L.filter(x=>x.d==d))}</div>`).join("")}<p class="warn" style="padding:0 16px">${T("schedNote")} <a href="https://sslgoldcup.worldofsailors.com/schedule/" target="_blank" rel="noopener">↗</a></p></details>`}

/* ---------- what each team needs before the final race ---------- */
const PERMS=(()=>{const o=[];const f=(a,r)=>{if(!r.length)return o.push(a);r.forEach((x,i)=>f([...a,x],r.filter((_,j)=>j!=i)))};f([],[0,1,2,3]);return o})();
const num=v=>parseFloat(String(v).replace(/[^\d.\-]/g,""))||0;
function needs(r,g){if(!["r32","r16","r8","r4"].includes(r.id))return null;const n=g.rows[0].r.length;if(n<2||g.rows.length!=4||!g.rows.every(x=>isTeam(x.team)))return null;
  const left=g.rows[0].r.map((_,i)=>g.rows.every(x=>String(x.r[i]??"").trim()==="")).filter(Boolean).length;
  if(left!=1||String(g.rows[0].r[n-1]??"").trim()!=="")return null;
  const base=g.rows.map(x=>x.r.reduce((s,v)=>s+num(v),0)),P=[8,6,4,2];
  const res=PERMS.map(pm=>{const tot=base.slice();pm.forEach((ti,pos)=>tot[ti]+=P[pos]);const pos=[];pm.forEach((ti,p)=>pos[ti]=p);
    return{pos,st:tot.map((t,i)=>{const ab=tot.filter((u,j)=>j!=i&&u>t).length,eq=tot.filter((u,j)=>j!=i&&u==t).length;return ab>=2?"out":ab+eq<=1?"in":"tie"})}});
  const N=T("need"),codes=g.rows.map(x=>x.team);
  return codes.map((c,i)=>{const at4=[0,1,2,3].map(p=>res.filter(o=>o.pos[i]==p));
    const cls=L=>L.every(o=>o.st[i]=="in")?"in":L.every(o=>o.st[i]=="out")?"out":L.some(o=>o.st[i]=="in")?"mix":L.some(o=>o.st[i]=="tie")?"tie":"out";
    const C=at4.map(cls);let txt,tie=false;
    if(C.every(x=>x=="in"))txt=N.sure;else if(C[0]=="out")txt=N.gone;
    else{let k=0;while(k<4&&C[k]=="in")k++;
      const cond=p=>{const L=at4[p];for(let j=0;j<4;j++){if(j==i)continue;const R=codes[j];const tests=[[o=>o.pos[j]>p,N.ahead(R)],[o=>o.pos[j]!=0,N.notWin(R)],[o=>o.pos[j]==3,N.last(R)],[o=>o.pos[j]==0,N.wins(R)],[o=>o.pos[j]<p,N.behind(R)]];
          for(const[f,t]of tests)if(L.every(o=>(o.st[i]=="in")==f(o))&&L.some(f))return t}return null};
      const ok=p=>ORD[lang](p+1);
      if(k==0){const c0=C[0]=="mix"?cond(0):null;txt=c0?N.mustIf(c0):N.mustWin+" "+N.help;if(C[0]=="tie")tie=true}
      else{txt=k==1?N.win:N.top(ok(k-1));if(k<4&&(C[k]=="mix"||C[k]=="tie")){const ck=C[k]=="mix"?cond(k):null;txt+=" · "+(ck?N.iff(ok(k),ck):N.maybe(ok(k)));if(C[k]=="tie"||at4[k].some(o=>o.st[i]=="tie"))tie=true}}
      if(!tie)tie=at4.slice(0,k+1).some(L=>L.some(o=>o.st[i]=="tie"))}
    return{c,txt,tie}})}
function needBox(r,g){const L=needs(r,g);if(!L)return"";return `<div class="need"><h4>${T("needT")}</h4><ul>${L.map(x=>`<li><b data-ot="${esc(x.c)}" role="button" tabindex="0">${FL(x.c)}${esc(x.c)}</b><span>${esc(x.txt)}${x.tie?" ≈":""}</span></li>`).join("")}</ul><small>${T("needNote")}</small></div>`}

/* ---------- views ---------- */
const raceNow=(rid,gid)=>SCH.some(x=>x.rid==rid&&(gid==null||x.g==gid)&&rState2(x)=="now");
const liveTag=()=>`<span class="dot live"></span><b class="lvtag">LIVE</b>`;
function ladder(){const L=$("#ladder");L.hidden=view!="board";if(L.hidden)return;
  const html=D.rounds.map(r=>{const s=rState(r),cls=s=="done"?"done":s=="live"?(raceNow(r.id)?"live":"amb"):(r.id==current()?"nx":"");
    return `<button data-r="${r.id}"><b>${esc(RS[r.id]||r.short)}</b><small><span class="dot ${cls}"></span>${esc(range(r))}</small></button>`}).join("");
  if(L.dataset.h!==html){L.innerHTML=html;L.dataset.h=html}
  L.querySelectorAll("button").forEach(b=>b.classList.toggle("on",b.dataset.r==round));
  const on=L.querySelector(".on");if(on){const x=on.offsetLeft-(L.clientWidth-on.offsetWidth)/2;try{L.scrollTo({left:x,behavior:RDIR?"smooth":"auto"})}catch(e){L.scrollLeft=x}}}
let RDIR=0;
function goRound(id){const ids=D.rounds.map(r=>r.id),a=ids.indexOf(round),b=ids.indexOf(id);if(b<0||id==round)return;RDIR=b>a?1:-1;round=id;go("round-"+id)}
