const pgHash=e=>e.t=="set"?"settings":e.t=="chg"?"changes":e.t=="rank"?"ranking":e.t=="fav"?"favorites":e.t=="tk"?"ticket":e.t=="bn"?"bonus":e.t=="sch"?"school":e.t=="schc"?`school-${e.id}`:e.t=="gl"?"glossary"+(e.id?"-"+e.id:""):e.t=="cmp"?"compare"+(e.m?"-"+e.m+(e.a||e.b?"-"+(e.a||"_"):"")+(e.b?"-"+e.b:""):""):e.t=="team"?`team-${e.a}`:e.t=="sailor"?`sailor-${e.a}-${e.i}`:e.t=="sx"?`sailorx-${e.s}`:`race-${e.k.replace(/\|/g,"-")}`;
function pgParse(h){let m;if(h=="settings")return{t:"set"};if(h=="changes")return{t:"chg"};if(h=="ranking")return{t:"rank"};if(h=="favorites")return{t:"fav"};if(h=="ticket")return{t:"tk"};if(h=="bonus")return{t:"bn"};if(h=="school")return{t:"sch"};if(m=h.match(/^school-([a-z]+)$/))return{t:"schc",id:m[1]};if(m=h.match(/^glossary(?:-([a-z0-9-]+))?$/))return{t:"gl",id:m[1]};if(m=h.match(/^compare(?:-(t|s)(?:-([A-Z]{3}(?:\.\d+)?|_))?(?:-([A-Z]{3}(?:\.\d+)?))?)?$/))return{t:"cmp",m:m[1]||"t",a:m[2]&&m[2]!="_"?m[2]:undefined,b:m[3]};if(m=h.match(/^team-([A-Z]{3})$/))return{t:"team",a:m[1]};if(m=h.match(/^sailor-([A-Z]{3})-(\d+)$/))return{t:"sailor",a:m[1],i:+m[2]};if(m=h.match(/^sailorx-([a-z0-9-]+)$/))return{t:"sx",s:m[1]};if(m=h.match(/^race-(\w+)-([A-D])-(\d+)$/))return{t:"race",k:`${m[1]}|${m[2]}|${m[3]}`};return null}
