  const pics=sq.ppl.filter(p=>p.img);
  if(pics.length)h+=`<div class="strip" aria-label="${esc(T("lineup"))}">${pics.map(p=>`<figure role="button" tabindex="0" data-pi="${p.i}"><img src="${esc(p.img)}" alt="${esc(p.name)}" loading="lazy"><figcaption><span class="fitn"><b>${/^\d+$/.test(p.no)?esc(p.no):""}</b> ${esc(surname(p.name))}</span>${p.k||p.cap?`<small class="fpos">${esc(p.k?posL(p):T("captain"))}</small>`:""}</figcaption></figure>`).join("")}</div>`;
  h+=`<div class="sstats"><button class="sl" data-rank="1"><small>${T("ranking")}</small><b id="rktile">${I.rank?"#"+I.rank:"–"}</b><em>${esc(T("rankBoard").replace(/\s*↗/,""))} ›</em></button>${TM?`<button class="sl" data-go="round-${TM.path[0].r.id}"><small>${T("entered")}</small><b>${esc(RNm(TM.path[0].r))}</b><em>${T("showRound")}</em></button>`:""}<button class="sl" data-go="gc2023"><small>${T("gc23")}</small><b>${esc(T("g23")[I.gc23||"none"])}</b><em>${T("br23")}</em></button>${lastP?`<button class="sl" data-go="round-${lastP.r.id}"><small>${T("status")}</small><b>${lastP.done&&(lastP.r.id=="f"||lastP.r.id=="pf")?esc(TM.txt):TM.out?T("stOut"):T("stIn")}</b><em>${TM.out?T("whereEnded"):T("curGroup")}</em></button>`:""}</div>`;
  h+=teamStats(TM);
  const R=I.route,qual=R&&/won|pos|lc/.test(R.k);
  const pnorm=x=>String(x).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim(),plink=nm=>{const k=pnorm(nm),P=sq.ppl.find(x=>pnorm(x.name)==k)||sq.ppl.find(x=>{const a=pnorm(x.name).split(/\s+/),b=k.split(/\s+/);return a[0]==b[0]&&a[a.length-1]==b[b.length-1]});return P?`<span class="plnk" role="button" tabindex="0" data-pi="${P.i}">${esc(nm)} ›</span>`:esc(nm)};
  h+=`<h3>${T("background")}</h3><div class="grp"><dl class="facts">${sq.c?`<dt>${T("captain")}</dt><dd>${plink(sq.c)}</dd>`:""}${I.helm?`<dt>${T("helm")}</dt><dd>${plink(I.helm)}</dd>`:""}<dt>${T("road")}</dt><dd>${esc(routeText(code,TM))}<br>${qual?`<a href="#qualifying" data-go="qualifying">${esc(T("qualRes").replace(/\s*↗/,""))} ›</a>`:`<a href="#ranking" data-rank="1">${esc(T("sslRank").replace(/\s*↗/,""))} ›</a>`}</dd>${I.note?`<dt>${T("story")}</dt><dd>${esc(I.note[lang]||I.note.en)}</dd>`:""}<dt>${T("site")}</dt><dd><a href="https://${esc(code.toLowerCase())}.sslgoldcup.com/" target="_blank" rel="noopener">${esc(T("teamSite"))} ↗</a></dd></dl></div>`;
  if(TM)h+=`<h3>${T("resRio")}</h3><div class="grp rt">${TM.path.map(p=>`<div style="padding:10px 16px 0;font-weight:600">${esc(RNm(p.r))} · ${T("group")} ${esc(p.g.id)} <span style="color:var(--mute);font-weight:400">${esc(range(p.r))}</span></div>${gtable(p.r,p.g,false)}`).join("")}</div>`;

