  d.querySelectorAll("[data-pi]").forEach(el=>{const f=()=>openSailor(code,+el.dataset.pi);el.onclick=f;el.onkeydown=e=>{if(e.key=="Enter")f()}});
  rkCur().then(W=>{const r=W&&W.n.find(x=>x[3]==code),el=d.querySelector("#rktile");if(r&&el&&PGS&&PGS.a==code)el.innerHTML=`#${r[0]} ${r[2]&&r[2]!=r[0]?rkTrend(r):""}`});
