const cmpP=v=>{const m=String(v||"").match(/^([A-Z]{3})\.(\d+)$/);if(!m)return null;let p=null;try{p=squad(m[1]).ppl[+m[2]]}catch(e){}return p?{c:m[1],p,PF:PROF[m[1]+"|"+p.name]||{}}:null};
