  const POS=["Helm","Tactician","Main Trimmer","Trimmer","Grinder","Pit","Mid-Bow","Bow"],F=[["all",esc(T("allS"))],["fav","★"],["cap",esc(T("svCaps"))]];if(cmpP(o))F.splice(1,0,["same",esc(T("cfSamePos"))]);POS.forEach(p=>F.push([p,esc(p)]));
