  d.querySelectorAll("[data-cpm]").forEach(b=>b.onclick=()=>{if(b.dataset.cpm==e.m)return;CMPK=null;CMPQ="";CMPF={t:"all",s:"all",tm:"",so:"rank"};pgGo({t:"cmp",m:b.dataset.cpm},true)});
