const tkSave=L=>LS.set("tickets",L.slice(0,30));
function tkId(){const d=new Date(),p=n=>String(n).padStart(2,"0");return `SSL-${String(d.getUTCFullYear()).slice(2)}${p(d.getUTCMonth()+1)}${p(d.getUTCDate())}-${Math.random().toString(36).slice(2,6).toUpperCase()}`}
function tkCtxInfo(){const ua=navigator.userAgent,os=/iPhone|iPad/.test(ua)?"iOS "+((ua.match(/OS (\d+[_\d]*)/)||[])[1]||"").replace(/_/g,"."):/Android/.test(ua)?"Android "+((ua.match(/Android ([\d.]+)/)||[])[1]||""):/Mac OS X/.test(ua)?"macOS":/Windows/.test(ua)?"Windows":"other";
  const br=/CriOS|Chrome\//.test(ua)?"Chrome":/FxiOS|Firefox\//.test(ua)?"Firefox":/Safari\//.test(ua)?"Safari":"other";
  return {version:"v"+CHL[0].v+(VER?" · "+String(VER).slice(0,7):""),page:TKFROM||location.hash||"#"+view,lang,device:`${os} · ${br} · ${innerWidth}×${innerHeight} @${devicePixelRatio||1}x`,mode:isStandalone()?"app":"browser",theme:document.documentElement.dataset.theme||"auto"}}
function tkText(t,pub){const C=TKX.en.tkCat;return `[${C[t.cat]}] ${t.title||t.txt.slice(0,60)}\n\n${t.txt}\n\n—\nTicket: ${t.id}\n${!pub&&t.name?"Name: "+t.name+"\n":""}${!pub&&t.mail?"E-mail: "+t.mail+"\n":""}${t.ctx?Object.entries(t.ctx).map(([k,v])=>k+": "+v).join("\n"):""}`}
function tkGhUrl(t){const C=TKX.en.tkCat;return TKREPO+"?labels="+encodeURIComponent({w:"wish",b:"bug",n:"note"}[t.cat]||"feedback")+"&title="+encodeURIComponent(`[${C[t.cat]}] ${(t.title||t.txt).slice(0,70)} (${t.id})`)+"&body="+encodeURIComponent(tkText(t,1).slice(0,5000))}
async function tkSend(t){if(!CFG.fb)return false;
  try{const r=await tfetch("https://formsubmit.co/ajax/"+encodeURIComponent(CFG.fb),{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({Ticket:t.id,Kategorie:TKX.de.tkCat[t.cat],Titel:t.title||"–",Beschreibung:t.txt,Name:t.name||"–",Kontakt:t.mail||"–",...(t.ctx?{Version:t.ctx.version,Seite:t.ctx.page,Sprache:t.ctx.lang,Geraet:t.ctx.device,Modus:t.ctx.mode,Theme:t.ctx.theme}:{}),_subject:`SSL App Ticket ${t.id} – ${TKX.de.tkCat[t.cat]}: ${(t.title||t.txt).slice(0,50)}`,_template:"table",_captcha:"false",...(t.mail?{_replyto:t.mail}:{})})},15000);
    const j=await r.json().catch(()=>({}));if(!r.ok||j.success===false||j.success==="false")throw new Error(j.message||r.status);return true}catch(e){return false}}
function openTicket(){TKFROM=location.hash&&!/^#ticket/.test(location.hash)?location.hash:"#"+view;TKLAST=null;PGPUSHED=true;pgGo({t:"tk"})}
function pTicket(){const d=$("#pg"),L=tkList(),C=T("tkCat"),ico={w:"💡",b:"🐞",n:"💬"};
  let h=`<div class="th"><button class="bk">${T("back")}</button><div class="thb"><button class="x" aria-label="${T("close")}">✕</button></div></div><div class="tb tkpg"><h2 class="fvh">${esc(T("tkT"))}</h2><p class="tksub">${esc(T("tkSub"))}</p>`;
  if(TKLAST){const t=TKLAST;h+=`<div class="tkdone ${t.st}"><b>${esc(t.st=="sent"?T("tkOk")(t.id):t.id)}</b>${t.st=="sent"?"":`<p>${esc(CFG.fb?T("tkErr"):T("tkNoDirect"))}</p><div class="tkbt"><a class="tbtn" href="${esc(tkGhUrl(t))}" target="_blank" rel="noopener" data-tkgh="${esc(t.id)}"><span>${esc(T("tkGh"))}</span><small>${esc(T("tkGhSub"))}</small></a><button class="tbtn" data-tkcp="${esc(t.id)}">${esc(T("tkCopy"))}</button>${CFG.fb?`<button class="tbtn" data-tkre="${esc(t.id)}">${esc(T("tkRetry"))}</button>`:""}</div>`}</div>`}
  h+=`<form class="tkf" novalidate><div class="tkcat" role="radiogroup">${["w","b","n"].map(k=>`<button type="button" role="radio" aria-checked="${TKC==k}" class="${TKC==k?"on":""}" data-tkc="${k}"><i>${ico[k]}</i><span>${esc(C[k])}</span></button>`).join("")}</div>
  <input name="t" maxlength="90" placeholder="${esc(T("tkTitle"))}" aria-label="${esc(T("tkTitle"))}">
  <textarea name="m" rows="6" maxlength="3000" placeholder="${esc(T(TKC=="b"?"tkPhB":TKC=="w"?"tkPhW":"tkPhN"))}" aria-label="${esc(C[TKC])}"></textarea>
  <div class="tk2"><input name="n" maxlength="80" autocomplete="name" placeholder="${esc(T("tkName"))}"><input name="e" type="email" maxlength="120" autocomplete="email" placeholder="${esc(T("tkMail"))}"></div>
  <input name="_honey" class="fbh" tabindex="-1" autocomplete="off" aria-hidden="true">
  <label class="tkctx"><input type="checkbox" name="c" checked><span><b>${esc(T("tkCtx"))}</b><small>${esc(T("tkCtxSub"))}</small><code>${esc(Object.values(tkCtxInfo()).join(" · "))}</code></span></label>
  <button class="obgo" type="submit"><span>${esc(T("tkSend"))}</span></button><p class="fbmsg" role="status"></p></form>`;
  if(L.length)h+=`<h3>${esc(T("tkMine"))}</h3><div class="grp tkl">${L.map(t=>`<div class="tkr"><i>${ico[t.cat]||"💬"}</i><span><b>${esc(t.title||t.txt.slice(0,70))}</b><small>${esc(t.id)} · ${esc(new Date(t.ts).toLocaleDateString(LOC(),{day:"numeric",month:"short"}))} · <em class="${t.st}">${esc(T("tkSt")[t.st]||t.st)}</em></small></span>${t.st=="sent"?"":`<button data-tkcp="${esc(t.id)}" aria-label="${esc(T("tkCopy"))}">⧉</button>`}</div>`).join("")}</div>`;
  d.innerHTML=h+`</div>`;
  const f=d.querySelector("form"),msg=d.querySelector(".fbmsg"),btn=f.querySelector(".obgo");
  d.querySelectorAll("[data-tkc]").forEach(b=>b.onclick=()=>{TKC=b.dataset.tkc;d.querySelectorAll("[data-tkc]").forEach(x=>{const on=x==b;x.classList.toggle("on",on);x.setAttribute("aria-checked",on)});f.m.placeholder=T(TKC=="b"?"tkPhB":TKC=="w"?"tkPhW":"tkPhN")});
  const find=id=>tkList().find(t=>t.id==id);
  d.querySelectorAll("[data-tkcp]").forEach(b=>b.onclick=async()=>{const t=find(b.dataset.tkcp);if(!t)return;try{await navigator.clipboard.writeText(tkText(t));toast(T("tkCopied"))}catch(e){}});
  d.querySelectorAll("[data-tkgh]").forEach(a=>a.addEventListener("click",()=>gcEvent("ticket-github")));
  d.querySelectorAll("[data-tkre]").forEach(b=>b.onclick=async()=>{const L=tkList(),t=L.find(x=>x.id==b.dataset.tkre);if(!t)return;b.disabled=true;if(await tkSend(t)){t.st="sent";tkSave(L);TKLAST=t;gcEvent("ticket-sent")}pTicket();d.scrollTop=0});
  f.onsubmit=async ev=>{ev.preventDefault();if(f._honey.value)return;const txt=f.m.value.trim();if(txt.length<10){msg.textContent=T("tkShort");f.m.focus();return}
    const t={id:tkId(),cat:TKC,title:f.t.value.trim(),txt,name:f.n.value.trim(),mail:f.e.value.trim(),ctx:f.c.checked?tkCtxInfo():null,ts:Date.now(),st:"local"};
    btn.disabled=true;msg.textContent="…";if(await tkSend(t))t.st="sent";const L=tkList();L.unshift(t);tkSave(L);TKLAST=t;gcEvent("ticket-"+TKC+(t.st=="sent"?"":"-local"));pTicket();d.scrollTop=0};
  pgShow(d)}
