for(const l in BNX)if(S[l])Object.assign(S[l],BNX[l]);
const BADGES=[["live","📺"],["days3","🔥"],["five","⭐"],["final","🏆"]];
var BNJ=null,BNSTREAM=null,BNMSG="";
const bnGot=()=>{const L=LS.get("bonus",[]);return Array.isArray(L)?L:[]};
async function bnLoad(){if(BNJ)return BNJ;try{const r=await fetch("bonus.json",{cache:"no-cache"});BNJ=r.ok?await r.json():{codes:[]}}catch(e){BNJ={codes:[]}}return BNJ}
async function bnHash(c){const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(String(c).trim().toUpperCase()+"|ssl-gc-rio"));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("").slice(0,20)}
function bnBadges(L){const days=new Set(L.map(x=>rioDay(x.ts))),has=new Set();if(L.length)has.add("live");if(days.size>=3)has.add("days3");if(L.length>=5)has.add("five");L.forEach(x=>{if(x.b)has.add(x.b)});return has}
const rioDay=ts=>new Date(ts-3*36e5).toISOString().slice(0,10);
async function bnRedeem(code){code=String(code||"").replace(/[^0-9A-Za-z]/g,"").toUpperCase();if(code.length<4)return["bad"];
  const J=await bnLoad(),h=await bnHash(code),now=nowMs(),G=15*6e4;
  const c=(J.codes||[]).find(x=>x.h==h&&(!x.f||Date.parse(x.f)-G<=now)&&(!x.u||now<=Date.parse(x.u)+G));if(!c)return["bad"];
  const L=bnGot();if(L.some(x=>x.h==h))return["dup"];
  const before=bnBadges(L);L.push({h,ts:now,b:c.b||null});LS.set("bonus",L);const after=bnBadges(L),nw=[...after].filter(b=>!before.has(b));
  gcEvent("bonus-redeem");return["ok",nw]}
function bnMsgFor(r){if(r[0]=="dup")return T("bnDup");if(r[0]=="bad")return T("bnBad");const B=T("bdg"),n=r[1]&&r[1][0];return T("bnGot")(n?B[n][0]:T("bnCodes")(bnGot().length))}
function bnStopCam(){try{if(BNSTREAM)BNSTREAM.getTracks().forEach(t=>t.stop())}catch(e){}BNSTREAM=null}
async function bnCam(d){const v=d.querySelector(".bnvid video"),box=d.querySelector(".bnvid");if(!v||!("BarcodeDetector" in window))return;
  try{const det=new BarcodeDetector({formats:["qr_code"]});BNSTREAM=await navigator.mediaDevices.getUserMedia({video:{facingMode:"environment"},audio:false});v.srcObject=BNSTREAM;await v.play();box.hidden=false;
    const tick=async()=>{if(!BNSTREAM)return;try{const R=await det.detect(v);const raw=R&&R[0]&&R[0].rawValue;if(raw){const m=String(raw).match(/[?&]bonus=([0-9A-Za-z-]+)/),code=m?m[1]:raw;bnStopCam();BNMSG=bnMsgFor(await bnRedeem(code));pBonus();return}}catch(e){}setTimeout(tick,250)};tick()}
  catch(e){bnStopCam();box.hidden=true;BNMSG=T("bnNoCam");pBonus()}}
function pBonus(){if(BNSTREAM)return;const d=$("#pg"),L=bnGot(),has=bnBadges(L),B=T("bdg"),J=BNJ,soon=J&&!(J.codes||[]).some(x=>!x.u||Date.parse(x.u)>nowMs()-864e5),cam="BarcodeDetector" in window&&navigator.mediaDevices;
  let h=`<div class="th"><button class="bk">${T("back")}</button><div class="thb"><button class="x" aria-label="${T("close")}">✕</button></div></div><div class="tb bnpg"><h2 class="fvh">${esc(T("bnT"))}</h2><p class="tksub">${esc(T("bnSub"))}</p>`;
  if(BNMSG)h+=`<div class="bnmsg">${esc(BNMSG)}</div>`;
  if(soon)h+=`<p class="bnsoon">⏳ ${esc(T("bnSoon"))}</p>`;
  h+=`<div class="bnhero"><div class="bnqr" aria-hidden="true">${svg('<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 14h3v3h-3zM20 14v.01M14 20h.01M17 20h4v-3"/>')}</div><div><b>${esc(T("bnCodes")(L.length))}</b><small>${has.size} / ${BADGES.length} ${esc(T("bnBadges"))}</small></div></div>`;
  h+=`<div class="bnvid" hidden><video playsinline muted></video><button class="tbtn" data-bnstop="1">${esc(T("bnStop"))}</button></div>`;
  h+=`<div class="bnact">${cam?`<button class="obgo" data-bncam="1"><span>📷 ${esc(T("bnScan"))}</span></button>`:`<p class="warn">${esc(T("bnNoCam"))}</p>`}<form class="bnf"><input name="c" maxlength="24" autocapitalize="characters" autocomplete="off" spellcheck="false" placeholder="${esc(T("bnEnter"))}" aria-label="${esc(T("bnEnter"))}"><button type="submit" class="tbtn">${esc(T("bnOk"))}</button></form></div>`;
  h+=`<h3>${esc(T("bnBadges"))}</h3><div class="bngrid">${BADGES.map(([k,ic])=>`<div class="bnb${has.has(k)?" on":""}"><i>${ic}</i><b>${esc(B[k][0])}</b><small>${esc(B[k][1])}</small></div>`).join("")}</div>`;
  h+=`<h3>${esc(T("bnHow"))}</h3><ol class="bnhow"><li>${esc(T("bnHow1"))}</li><li>${esc(T("bnHow2"))}</li><li>${esc(T("bnHow3"))}</li></ol>`;
  d.innerHTML=h+`</div>`;BNMSG="";
  const cb=d.querySelector("[data-bncam]");if(cb)cb.onclick=()=>bnCam(d);const sb=d.querySelector("[data-bnstop]");if(sb)sb.onclick=()=>{bnStopCam();d.querySelector(".bnvid").hidden=true};
  const f=d.querySelector(".bnf");f.onsubmit=async ev=>{ev.preventDefault();BNMSG=bnMsgFor(await bnRedeem(f.c.value));pBonus()};
  pgShow(d);if(!BNJ)bnLoad().then(()=>{if(PGS&&PGS.t=="bn"&&!$("#pg").hidden)pBonus()})}
function openBonus(){PGPUSHED=true;pgGo({t:"bn"})}
/* ?bonus=CODE from a QR in the broadcast: redeem, clean the URL, show the bonus page */
setTimeout(async()=>{try{const q=new URLSearchParams(location.search),c=q.get("bonus");if(!c)return;q.delete("bonus");const qs=q.toString();history.replaceState(history.state,"",location.pathname+(qs?"?"+qs:"")+location.hash);
  BNMSG=bnMsgFor(await bnRedeem(c));gcEvent("bonus-scan");openBonus()}catch(e){}},1200);
