function schBack(){return `<div class="th"><button class="bk">${T("back")}</button><div class="thb"><button class="x" aria-label="${T("close")}">✕</button></div></div>`}
function schWait(d,fn){d.innerHTML=schBack()+`<div class="tb"><p class="warn">${esc(T("svLoad"))}</p></div>`;pgShow(d);schLoad().then(()=>{if(PGS&&(PGS.t=="sch"||PGS.t=="schc"||PGS.t=="gl"))fn()})}
function pSchool(){const d=$("#pg"),S0=schCur();if(!S0)return schWait(d,pSchool);const done=schDone(),fb=!SCHL.includes(lang);
  let h=schBack()+`<div class="tb sch"><div class="schhero"><div class="schhi">${schIcon("course")}</div><small>SSL GOLD CUP · RIO 2026</small><h2>Sailing School</h2><p>${esc(T("schSub"))}</p><div class="schprog"><i style="width:${Math.round(Object.keys(done).length/S0.chapters.length*100)}%"></i></div><em>${Object.keys(done).length} / ${S0.chapters.length}</em></div>`;
  if(fb)h+=`<p class="schfb">🌐 ${esc(T("schFb"))}</p>`;
  h+=`<div class="schvid"><span class="xi" style="--c:#ff4d4d">${schIcon("vid")}</span><span><b>${esc(T("schVid"))}</b><small>${esc(T("schVidSub"))}</small></span><em>${esc(T("schSoon"))}</em></div>`;
  h+=`<div class="schl">${S0.chapters.map((c,i)=>`<button class="schc${done[c.id]!=null?" done":""}" data-schc="${esc(c.id)}"><span class="schn">${done[c.id]!=null?"✓":i+1}</span><span class="schci">${schIcon(c.id)}</span><span class="schct"><small>${esc(T("schCh")(i+1))}${c.quiz&&c.quiz.length?` · ${esc(T("schQuiz"))}`:""}</small><b>${esc(c.t)}</b><em>${esc(c.sub)}</em></span><i aria-hidden="true">›</i></button>`).join("")}</div>`;
  h+=`<button class="schg" data-glp="1"><span class="xi" style="--c:#9b8cff">${schIcon("gl")}</span><span><b>${esc(T("schGl"))}</b><small>${esc(T("schGlSub")(S0.glossary.length))}</small></span><i aria-hidden="true">›</i></button></div>`;
  d.innerHTML=h;d.querySelectorAll("[data-schc]").forEach(b=>b.onclick=()=>pgGo({t:"schc",id:b.dataset.schc}));d.querySelector("[data-glp]").onclick=()=>pgGo({t:"gl"});gcEvent("school");pgShow(d)}
function schQuizH(c,GL){const q=c.quiz||[];if(!q.length)return"";const st=SCHQ[c.id]||(SCHQ[c.id]={i:0,a:[]});
  if(st.i>=q.length){const ok=st.a.filter(Boolean).length;return `<div class="schq fin"><b>${ok==q.length?"🏆":ok>=q.length/2?"👍":"💪"}</b><h3>${esc(T("schScore")(ok,q.length))}</h3><button class="tbtn" data-qagain="1">${esc(T("schAgain"))}</button></div>`}
  const Q=q[st.i],ans=st.pick!=null;
  return `<div class="schq"><small>${esc(T("schQuiz"))} · ${esc(T("schQ")(st.i+1,q.length))}</small><h3>${esc(Q.q)}</h3>${Q.svg?schSvg(Q.svg,GL):""}<div class="schqa">${Q.a.map((a,j)=>`<button data-qa="${j}" class="${ans?(j==Q.c?"ok":j==st.pick?"no":"dim"):""}"${ans?" disabled":""}>${esc(a)}</button>`).join("")}</div>${ans?`<p class="schqe ${st.pick==Q.c?"ok":"no"}"><b>${esc(st.pick==Q.c?T("schRight"):T("schWrong"))}</b> ${esc(Q.e)}</p><button class="obgo" data-qnext="1"><span>${esc(st.i+1<q.length?"›":"✓")}</span></button>`:""}</div>`}
